    CG_=model.__dict__.setdefault('_vpC',{}); Cb_=Ha_.t()@Ha_/n_
    CG_[d]=Cb_ if d not in CG_ else cfg.varpro_beta*CG_[d]+(1.0-cfg.varpro_beta)*Cb_
