    def true_dom(s): return s.sch[min(s.vi,len(s.sch)-1)]
    def __call__(s):
        t=s.sch[s.vi]; b=s.tr(t,s.vi//s.nd)(); s.pos+=1; s.k+=1
        if s.k>=s.L: s.k=0; s.vi+=1
