        w=np.array(s.rw); med=float(np.median(w)); sd=max(float(c.stream_rep_floor),1.4826*float(np.median(np.abs(w-med)))); z=(r-med)/sd
        if z>float(c.stream_rep_z): s.rz=z; return True
