            Yn,ln=_cd_gen_slot(model,cfg,st0,m,L,dom,M,temp,g_,forced,flen,ban,hint)
            same_=float((Yo==Yn).float().mean()); fin_=torch.isfinite(lo)&torch.isfinite(ln)
