                new_.append({'A':A.decode(),'B':B.decode(),'C':C.decode(),'r':(r1_,r2_),'typed':typed_,'s':sent_,'src':(ia_,ic_),'d':S_['it'][ia_]['d'],
                             'dep':1+S_['it'][ia_]['dep']+S_['it'][ic_]['dep'],'gain':gain_,'fanpen':math.log2(max(1,f0_*(f0_-1)/2))})
