    import zlib as _zl
    ord_=str(getattr(cfg,'inf_sleep_order','nrem')); FX_=S_.get('facts',[]) if ord_!='nrem' else []; REMk_=int(getattr(cfg,'inf_sleep_cycles',1)) if ord_=='nrem_rem' else 0; remd_=0
    PN_=S_.setdefault('pruned_names',set())
