                facts_=[(N_[i_],R_[i_],N_[i_+1]) for i_ in range(depth_)]; brk_=None
                if dec_: brk_=1+rs_.randint(depth_-1) if depth_>1 else 0; facts_[brk_]=(fresh(),R_[brk_],N_[brk_+1])   # the chain breaks: N_brk has no R_brk fact
